from fastapi import FastAPI
from pydantic import BaseModel, computed_field
from fastapi.testclient import TestClient
import json

app = FastAPI(separate_input_output_schemas=False)

class Item(BaseModel):
    name: str

    @computed_field
    @property
    def description(self) -> str:
        return f"Description of {self.name}"

@app.get("/item", response_model=Item)
def read_item():
    return Item(name="test")

client = TestClient(app)

def test_openapi_schema():
    response = client.get("/openapi.json")
    schema = response.json()

    # Find the Item schema
    # It should be in components/schemas
    item_schema = schema["components"]["schemas"]["Item"]
    print(json.dumps(item_schema, indent=2))

    assert "description" in item_schema["properties"], "Computed field 'description' should be in the OpenAPI schema"

if __name__ == "__main__":
    try:
        test_openapi_schema()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

